export function topicMedia(projectId: string, topic: string, technical = false) { return artifacts.filter(a => a.media?.publication === "approved" && a.media.projectId === projectId && (technical ? a.media.technicalTopics : a.media.topics).includes(topic)); }
export function projectDemo(projectId: string) { return artifacts.find(a => a.media?.projectId === projectId && a.media.kind === "demonstration" && a.media.publication === "approved"); }

export function findProject(slug: string) { return projects.find((project) => project.slug === slug); }
export function findArtifact(id: string) { return artifacts.find((artifact) => artifact.id === id); }

export type RichBlock = { id: string; source: string; kind: "paragraph" | "emphasis" | "heading"; text: string };

