export const layer3: Record<string, { id: string; title: string; source: string; paragraphs: string[]; artifact: string }[]> = {
  "spiral-one": [
    { id: "overview", title: "Technical architecture", source: "Layer 3 · pp. 1–2", artifact: "s1-c01", paragraphs: ["Spiral One is a local-first control plane around AI-assisted software development. The distinction I make is that the model is not the development system. The model is one worker inside a larger system that owns more of the continuity around the work.", "The control surface is built in Next.js, React and TypeScript. Provider execution currently connects through the Codex App Server protocol. Around that, Spiral One maintains its own execution services, context compilation, adaptive objectives, runtime threads, verification evidence and local durable state.", "Execution is sequential in the implemented workflow. Spiral One is not currently a parallel autonomous-agent swarm, a cloud scheduler or a complete replacement for the underlying provider environment."] },
    { id: "context", title: "Context compiler + reference intelligence", source: "Layer 3 · pp. 2–3", artifact: "s1-reference", paragraphs: ["Source material can be ingested and decomposed into smaller, addressable knowledge objects rather than remaining one giant document the model has to reread.", "Those objects retain relationships and provenance back to their source. Retrieval can be scoped around objective, component, failure mode and constraints, then compiled into a bounded brief for the work in front of the model.", "The point isn't to permanently compress everything. It's to avoid spending context and reasoning on information that has nothing to do with the current decision."] },
    { id: "routing", title: "Adaptive execution + model routing", source: "Layer 3 · pp. 3–4", artifact: "s1-workspace", paragraphs: ["Adaptive execution starts with the objective rather than immediately handing the whole thing to a model. For work complex enough to require decomposition, Spiral One can create sequential execution units and compile context for each attempt.", "Routing can consider runtime availability and characteristics of the work when selecting model and reasoning effort. Manual mode still lets me explicitly select the model and effort when I want direct control.", "The current cold-start router is a versioned, evidence-generating heuristic. I don't describe it as a learned ML routing policy."] },
    { id: "council", title: "Spiral Council", source: "Layer 3 · pp. 4–5", artifact: "s1-council", paragraphs: ["Council sits upstream of decisions that benefit from more than one perspective. The perspectives can evaluate architecture, user interaction, failure modes, assumptions and objective alignment.", "The outputs remain distinguishable long enough to expose disagreement, overlooked constraints and competing priorities. Findings can then be synthesized into something actionable.", "Council isn't required for every task. Sometimes the answer really is just change the button."] },
    { id: "verify", title: "Evidence-based verification", source: "Layer 3 · pp. 5–6", artifact: "s1-fhra", paragraphs: ["Provider completion and objective verification are separate states in Spiral One. A model can report that it changed something successfully. Spiral One can then ask whether there is independent evidence supporting that claim.", "Evidence can include terminal state, command exit codes, declared artifacts, expected files, file inspection, tests and acceptance evidence.", "The flow is Execution Complete → Collect Evidence → Compare Against Objective → Verified / Unsupported / Requires Inspection."] },
    { id: "fhra", title: "Fractal Holistic Recursive Audit", source: "Layer 3 · pp. 6–8", artifact: "s1-fhra", paragraphs: ["FHRA is essentially Spiral One's multi-scale inspection system. The same change can be evaluated across component, interaction, screen, workflow, product and system.", "The recursive part matters because findings can produce another intervention, which can then be inspected again: Inspect → Find → Correct → Zoom Out → Reinspect → Repeat.", "A route-contract fixture demonstrates this at a scoped level. It is not presented as proof of full recursive cross-scale correction."] },
    { id: "learn", title: "Empirical Knowledge Ledger", source: "Layer 3 · pp. 8–9", artifact: "s1-ledger", paragraphs: ["The Empirical Knowledge Ledger is where individual builds can start becoming reusable experience. I care about what was attempted, under what conditions, what actually happened, what evidence supports that outcome, whether it generalized and whether we should use it again.", "A single successful attempt doesn't automatically become a universal rule. Some knowledge stays project-specific. Some belongs as a heuristic. Some earns confidence because it keeps surviving different builds.", "When something becomes repeatable and measurable, it may become a deterministic check, a guardrail, a default or another piece of infrastructure."] },
    { id: "recovery", title: "Durable state + recovery", source: "Layer 3 · pp. 9–11", artifact: "s1-runtime", paragraphs: ["Spiral One deliberately separates provider-thread state from Spiral-owned state. The provider owns the active provider interaction. Spiral One owns durable records around the work.", "An interruption can be represented honestly: Running → Interrupted → Reconcile → Paused / Recoverable → Inspect → Resume.", "Recovery is moving toward stronger self-modification boundaries, but validated source rollback and known-good promotion are direction, not current capability."] },
  ],
  "courier-copilot": [
    { id: "pipeline", title: "OCR + decision pipeline", source: "Layer 3 · pp. 11–12", artifact: "cc-test", paragraphs: ["Courier Copilot is deterministic. There isn't an LLM sitting between the offer and the recommendation.", "The current iPhone pipeline is Visible Offer → ReplayKit → Frame Sampling → Vision OCR → Field Parsing → Calculations → Threshold Rules → GREEN / YELLOW / RED → Notification.", "The resulting signal is advisory. Courier Copilot doesn't connect to an Uber API and doesn't accept or reject an offer."] },
    { id: "field-testing", title: "OCR failure handling + resource constraints", source: "Layer 3 · pp. 12–13", artifact: "cc-test", paragraphs: ["OCR in a live courier interface is messy. Frames change. Animations happen. Text can appear partially. A value can be misread before a later frame produces the correct result.", "The engineering problem is deciding when an observation is trustworthy enough to act on while staying fast enough to return something useful inside a short offer window.", "Resource usage became part of correctness. A decision assistant that interferes with the courier app, navigation or the phone itself isn't working correctly even if its OCR output is technically accurate."] },
    { id: "scoring", title: "Local data + future personalization", source: "Layer 3 · pp. 13–14", artifact: "cc-test", paragraphs: ["The current system can preserve structured information about evaluated offers. That creates a foundation for offers, outcomes, merchant history, area and time patterns, and personal baselines.", "That is future direction, not current functionality. The current prototype evaluates visible offers using configured deterministic rules.", "It doesn't currently claim predictive market intelligence or demonstrated earnings improvement."] },
  ],
  "pocket-spiral": [
    { id: "inference", title: "On-device inference", source: "Layer 3 · pp. 14–15", artifact: "ps-benchmark", paragraphs: ["Pocket Spiral moves the core inference path onto the device: Model File → GGUF → Local Runtime → Model Load → Prompt → On-Device Inference → Response.", "Supported GGUF models can be loaded into the local runtime and executed directly on the iPhone rather than sending every prompt to a hosted model provider.", "Pocket Spiral became as much an experiment in resource-aware AI as local inference itself."] },
    { id: "device", title: "Device constraints as product constraints", source: "Layer 3 · pp. 15–16", artifact: "ps-benchmark", paragraphs: ["If inference consumes too much memory, gets too slow, or drives the device thermally into the ground, the person is literally holding the problem in their hand.", "The useful boundary has to account for model size, available memory, latency, thermal behavior and sustained usability.", "The current prototype proves useful language-model inference can run locally on a physical device with supported models. It does not claim all AI is offline or comfortable for all-day use."] },
  ],
  quel: [
    { id: "interaction-model", title: "Interaction model", source: "Layer 3 · pp. 16–17", artifact: "q-c01", paragraphs: ["Levo's core interaction is intentionally bounded. The user starts with an intensity from 1–100. That maps into Green: 1–14, Yellow: 15–39, Orange: 40–69, and Red: 70–100.", "Intensity → Zone → Bounded Skills → Selection → Event Record → Optional After-State → History / Patterns.", "As intensity increases, the system should not respond by becoming more complicated. It should become simpler."] },
    { id: "local-data", title: "Local data model", source: "Layer 3 · pp. 17–18", artifact: "q-migration", paragraphs: ["Levo uses versioned local event storage for details such as time, intensity, trigger, description, tags, selected skills, distress afterward and effectiveness.", "The schema is versioned because the data model will change. Existing records need a defined path forward, and decode failures need safe handling rather than silently destroying someone's history.", "The iOS implementation currently goes further than the Android pilot, and I don't present them as being at complete feature parity."] },
    { id: "safety", title: "Safety invariants", source: "Layer 3 · pp. 18–20", artifact: "levo-skill", paragraphs: ["Safety requirements are treated more like architecture than copywriting. Constraints include keeping support reachable, avoiding pathologizing language, simplifying at higher intensity and handling stored information safely.", "Levo is a DBT-informed skills and reflection companion. It is not therapy, diagnosis, crisis intervention or a clinically validated treatment product.", "Cross-platform parity is something to verify, not assume because two apps share a product name."] },
  ],
  "ai-memory-card": [
    { id: "ingestion", title: "Ingestion + normalization pipeline", source: "Layer 3 · pp. 20–21", artifact: "amc-import", paragraphs: ["AI Memory Card starts with user-provided exports rather than live account access: ChatGPT / Claude / Gemini Export → Provider Parser → Normalization → Deduplication → Structured Archive → Search / Recall.", "Normalization preserves useful conversation metadata alongside actual content. Deduplication prevents repeated imports from quietly turning the archive into multiple copies of the same history.", "A recorded import produced 29,453 entries from 327 conversations across four input files."] },
    { id: "portability", title: "Portable recall", source: "Layer 3 · pp. 21–22", artifact: "amc-c01", paragraphs: ["Portable recall helps move relevant history into another environment as text rather than requiring the next model to have direct access to the original provider.", "It isn't direct model-memory injection. It isn't live synchronization. It isn't vector search. It's a deliberately simpler portability mechanism.", "The user has an artifact. The artifact is readable. It can move."] },
    { id: "boundaries", title: "Local default + optional webhook", source: "Layer 3 · pp. 22–23", artifact: "amc-c01", paragraphs: ["The default workflow is local. Exports are supplied by the user, processed locally, and turned into local archive and recall artifacts.", "There is an optional webhook path for deliberately configured workflows that need to send structured data elsewhere.", "AI Memory Card is an archive and portability utility. It does not provide live provider synchronization, semantic or vector search, direct memory writing, guaranteed perfect extraction or guaranteed improvement in future model responses."] },
  ],
};
